query LoanSnapshot($input: LoansInput) {
  liqwid {
    data {
      loans(input: $input) {
        totalCount
        page
        perPage
        pagesCount
        results {
          id
          marketId
          publicKey
          amount(input: { currency: USD })
          adjustedAmount(input: { currency: USD })
          collateral(input: { currency: USD })
          healthFactor
          LTV
          APY
          collaterals {
            id
            qTokenName
            qTokenAmount
            amountInUsd: amount(input: { currency: USD })
            market {
              id
              displayName
            }
          }
        }
      }
    }
  }
}
